import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from sklearn.preprocessing import StandardScaler

MAX_DRIVERS = 5

def design(feats):
    # Filter to significant features based on t-test
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if abs(stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i]).statistic) > 2.0:
            sig_features.append(fid)

    # Remove near-duplicates (correlated pairs with |r| >= 0.6)
    keep = set()
    correlated = set()
    for fid in sig_features:
        if fid in correlated:
            continue
        keep.add(fid)
        for other_fid in sig_features:
            if other_fid == fid or other_fid in correlated:
                continue
            corr = np.corrcoef(feats.x[:, feats.column(fid)], feats.x[:, feats.column(other_fid)])[0,1]
            if abs(corr) >= 0.6:
                correlated.add(other_fid)

    sig_features = list(keep)

    # If no significant features, return empty design
    if not sig_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select top features by effect size
    effects = []
    for fid in sig_features:
        col = feats.column(fid)
        effect = abs(np.mean(feats.x[feats.y==1, col]) - np.mean(feats.x[feats.y==0, col]))
        effects.append((effect, fid))

    effects.sort(reverse=True)
    drivers = [fid for _, fid in effects[:MAX_DRIVERS]]

    # Build columns and products
    columns = sig_features
    products = []

    # Add interaction terms between top features
    for i, fid1 in enumerate(drivers):
        for j, fid2 in enumerate(drivers[i+1:], i+1):
            products.append((fid1, fid2))

    # Create weighted score using top features
    loadings = {}
    for fid in drivers:
        col = feats.column(fid)
        effect = np.mean(feats.x[feats.y==1, col]) - np.mean(feats.x[feats.y==0, col])
        loadings[fid] = effect

    return Design(drivers=tuple(drivers), columns=tuple(columns), products=tuple(products), loadings=loadings)

